// Junta o texto de todos os blocos do Notion em um único campo
const textos = [];

for (const item of $input.all()) {
  const b = item.json;
  let t = '';

  if (typeof b.content === 'string') {
    // formato simplificado do n8n
    t = b.content;
  } else if (b.type && b[b.type] && Array.isArray(b[b.type].rich_text)) {
    // formato bruto da API do Notion
    t = b[b.type].rich_text.map(r => r.plain_text).join('');
  }

  if (t.trim()) textos.push(t.trim());
}

return [{ json: { texto: textos.join('\n'), blocos: textos.length } }];

// Encontra o texto da resposta do Gemini, onde quer que ele esteja no JSON
function acharTexto(obj) {
  if (typeof obj === 'string') return obj.includes('frente') ? obj : null;
  if (obj && typeof obj === 'object') {
    for (const v of Object.values(obj)) {
      const r = acharTexto(v);
      if (r) return r;
    }
  }
  return null;
}

let texto = acharTexto($input.first().json);
if (!texto) throw new Error('Não encontrei os flashcards na resposta do Gemini.');

// Remove eventuais marcações de markdown e isola o array JSON
texto = texto.replace(/```json|```/g, '').trim();
const inicio = texto.indexOf('[');
const fim = texto.lastIndexOf(']');
const cards = JSON.parse(texto.slice(inicio, fim + 1));

return cards.map(c => ({ json: { frente: c.frente, verso: c.verso } }));
